# [역할: 당신은 소설 속 "{{name}}"({{role}})입니다]
당신은 지금부터 소설 속 등장인물 "{{name}}" 본인이 되어 모든 대화와 행동을 100% 캐릭터의 관점에서 직접 수행합니다.

## 1. 인물 기본 정체성 (Core Identity)
- 이름: {{name}} ({{role}})
- 신분/프로필: {{profile_summary}}
- 외모/복장: {{appearance}}

## 2. 성격 및 내면 심리 (Personality)
{{personality}}

## 3. 고유 말투 및 호칭 규칙 (Speech Tone)
- 어조 및 호칭: {{speech_tone}}
- 특유의 행동/버릇: {{behavior_patterns}}

## 4. 대표 대사 예시 (말투/톤 모방 가이드)
{{dialogue_examples}}

code:
// 1) 이름 / 역할 파싱
const nameRoleRaw = input.name_role || input.name || '';
let charName = '';
let charRole = '';
if (nameRoleRaw.includes('/')) {
  const parts = nameRoleRaw.split('/');
  charName = parts[0].trim();
  charRole = parts.slice(1).join('/').trim();
} else {
  charName = nameRoleRaw.trim();
  charRole = (input.role || '').trim();
}
charName = charName || '미정';
charRole = charRole || '등장인물';

// 2) 호불호 파싱
const prefRaw = input.preferences || '';
let likesRaw = input.likes || '';
let dislikesRaw = input.dislikes || '';
if (prefRaw.includes('/')) {
  const parts = prefRaw.split('/');
  likesRaw = parts[0].trim();
  dislikesRaw = parts.slice(1).join('/').trim();
} else if (prefRaw) {
  likesRaw = prefRaw.trim();
}
const likesList = likesRaw.split(/[\n,]+/).map(s => s.trim()).filter(Boolean);
const dislikesList = dislikesRaw.split(/[\n,]+/).map(s => s.trim()).filter(Boolean);

// 3) 대사 및 버릇 파싱
const dialogueList = (input.dialogue_examples || '').split('\n').map(s => s.trim()).filter(Boolean);
const habitList = (input.behavior_patterns || '').split('\n').map(s => s.trim()).filter(Boolean);

// 4) 로어 전체 JSON 구조화
const loreJson = {
  name: charName,
  role: charRole,
  profile: input.profile_summary || '',
  appearance: input.appearance || '',
  personality: { description: input.personality || '' },
  speech_style: {
    tone: input.speech_tone || '',
    examples: dialogueList
  },
  behavior_patterns: { common_habits: habitList },
  knowledge: input.knowledge || '',
  memories: input.memories || '',
  special_ability: input.special_ability || '',
  preferences: {
    likes: likesList,
    dislikes: dislikesList
  },
  past_background_and_motivation: input.past_and_motivation || '',
  extra_notes: input.extra_notes || ''
};

// 5) 마크다운 변수 치환
const vars = {
  name: charName,
  role: charRole,
  profile_summary: input.profile_summary || '',
  profile: input.profile_summary || '',
  appearance: input.appearance || '',
  personality: input.personality || '',
  speech_tone: input.speech_tone || '',
  dialogue_examples: dialogueList.map(d => '- ' + d).join('\n'),
  behavior_patterns: habitList.join(', '),
  knowledge: input.knowledge || '',
  memories: input.memories || '',
  special_ability: input.special_ability || '',
  likes: likesList.join(', ') || likesRaw,
  dislikes: dislikesList.join(', ') || dislikesRaw,
  past_and_motivation: input.past_and_motivation || '',
  extra_notes: input.extra_notes || ''
};

function renderTemplate(tpl, data) {
  return tpl.replace(/\{\{\s*(\w+)\s*\}\}|\{\s*(\w+)\s*\}/g, (match, p1, p2) => {
    const k = p1 || p2;
    return data[k] !== undefined ? data[k] : match;
  });
}

let rawTemplate = (input.custom_persona_md || '').trim();

if (!rawTemplate) {
  rawTemplate = '# [역할: 당신은 소설 속 "' + charName + '"(' + charRole + ')입니다]\n당신은 지금부터 소설 속 등장인물 "' + charName + '" 본인이 되어 모든 대화와 행동을 100% 캐릭터의 관점에서 직접 수행합니다.\n\n## 1. 인물 기본 정체성 (Core Identity)\n- 이름: {{name}} ({{role}})\n- 신분/프로필: {{profile_summary}}\n- 외모/복장: {{appearance}}\n\n## 2. 성격 및 내면 심리 (Personality)\n{{personality}}\n\n## 3. 고유 말투 및 호칭 규칙 (Speech Tone)\n- 어조 및 호칭: {{speech_tone}}\n- 특유의 행동/버릇: {{behavior_patterns}}\n\n## 4. 대표 대사 예시 (말투/톤 모방 가이드)\n{{dialogue_examples}}';
}

const personaMd = renderTemplate(rawTemplate, vars);

return {
  '등장인물 데이터': {
    name: charName,
    role: charRole,
    lore: loreJson,
    persona_md: personaMd
  }
};

// 1. inputToggles 상태 확인
const inputToggles = input.inputToggles || {};
const rawInputs = input.rawInputs || {};

// 2. 전체 상위 노드 및 스위치 ON된 선택 상위 노드 분류 수집
const allItems = [];
const allTexts = [];
const selectedItems = [];
const selectedTexts = [];

function harvest(key, val) {
  if (val === undefined || val === null || val === '') return;

  const isOff = inputToggles[key] === false;

  if (Array.isArray(val)) {
    val.forEach((sub, idx) => harvest(`${key}_${idx}`, sub));
  } else if (typeof val === 'object') {
    if (val.output !== undefined) {
      harvest(key, val.output);
    } else {
      const textVal = typeof val.text === 'string' ? val.text : (val.content || val.editorVal || val.val || JSON.stringify(val, null, 2));
      allItems.push(val);
      allTexts.push(textVal);
      if (!isOff) {
        selectedItems.push(val);
        selectedTexts.push(textVal);
      }
    }
  } else {
    const textVal = String(val);
    const obj = { source: key, text: textVal };
    allItems.push(obj);
    allTexts.push(textVal);
    if (!isOff) {
      selectedItems.push(obj);
      selectedTexts.push(textVal);
    }
  }
}

Object.entries(rawInputs).forEach(([k, v]) => harvest(k, v));

const selectedMergedText = (input.input || selectedTexts.join('\n\n')).trim();
const fullMergedText = allTexts.join('\n\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\n');

return {
  '🎯 선택된 텍스트': selectedMergedText || '(선택된 데이터가 없습니다. 상단 스위치를 켜주세요.)',
  '🗂️ 선택된 원본 배열 (데이터)': {
    count: selectedItems.length,
    items: selectedItems,
    structured: selectedItems,
    text: selectedMergedText
  },
  '📦 전체 원본 데이터 (통과)': {
    count: allItems.length,
    items: allItems,
    structured: allItems,
    text: fullMergedText
  }
};

const choice = input.selectedOption || input.selectedChoice || 'A';
const dataA = input['선택지 A 데이터'] || input['in_1'] || '';
const dataB = input['선택지 B 데이터'] || input['in_2'] || '';
const result = (choice === 'B' || choice === 'in_2') ? dataB : dataA;
return { '최종 선택 데이터': result || '(선택된 데이터 내용 없음)' };

const provider = input['AI 플랫폼'] || input.provider || 'Google (Gemini)';
const model = input['AI 모델'] || input.model || 'gemini-3.5-flash';
const apiKey = input['API Key'] || input.apiKey || '';
const temperature = parseFloat(input['창의성 (Temperature)'] || input.temperature || '0.7');
return {
  'AI 설정 데이터': {
    provider,
    model,
    apiKey: apiKey ? (apiKey.slice(0, 7) + '...' + apiKey.slice(-4)) : '(API Key 미설정)',
    rawApiKey: apiKey,
    temperature: isNaN(temperature) ? 0.7 : temperature
  }
};

// 1. 설정 및 프롬프트 수신
const config = inputs['⚡ AI 환경 설정 (필수)'] || inputs['in_ai_config'] || inputs['AI 설정'] || {};
let prompt = inputs['📝 프롬프트 / 본문 (필수)'] || inputs['in_prompt'] || inputs['프롬프트 / 본문'] || '';

if (prompt && typeof prompt === 'object') {
  prompt = prompt.content || prompt.text || prompt.summary || JSON.stringify(prompt);
}
prompt = String(prompt || '').trim();

if (!prompt) {
  return {
    '📜 생성 결과': '(입력 포트에 프롬프트 또는 텍스트가 연결되지 않았습니다.)'
  };
}

let generatedText = '';

try {
  generatedText = await window.aiApi.call(config, '', prompt);
} catch (err) {
  generatedText = `[AI 생성 오류: ${err.message}]`;
}

return {
  '📜 생성 결과': generatedText
};

const bgLore = (input.background_lore || '').trim();
return {
  '세계관 데이터': {
    title: input.title || '',
    tags: input.tags || input.genre || '',
    logline: input.logline || '',
    background_lore: bgLore
  }
};

const term = (input.term || '').trim();
const desc = (input.desc || '').trim();
const type = input.type || '고유명사';

return {
  '고유명사 데이터': {
    type: type,
    term: term,
    desc: desc,
    keywords: input.keywords || ''
  }
};

return {
  '스타일 가이드': {
    project_meta: {
      role: input.role || '',
      task: '소설 본문 및 씬 설계도 작성'
    },
    core_experience_goal: {
      primary_emotion: input.experience_goal || '',
      narrative_focus: '주인공의 능력과 문제 해결, 히로인과의 상호작용'
    },
    writing_style_guide: {
      narrative_perspective: input.narrative_perspective || '3인칭 전지적 작가 시점',
      tone_and_style: input.tone_style || '',
      writing_rules: (input.writing_rules || input.formatting_rules || '').split('\n').filter(Boolean)
    }
  }
};

const events = (input.must_include_events || '').split('\n').filter(Boolean);
return {
  '챕터 스코프': {
    episode_notation: input.episode_notation || '',
    scene_goal: input.scene_goal || '',
    must_include_events: events.length > 0 ? events : [(input.must_include_events || '')]
  }
};

const hookId = input.hook_id || '복선';
const truth = input.hidden_truth || '';
const clue = input.observable_clue || '';
const stage = input.reveal_stage || '';

return {
  '복선 데이터': {
    hook_id: hookId,
    hidden_truth: truth,
    observable_clue: clue,
    reveal_stage: stage
  }
};

return {
  'AI 작업 지시': {
    request: {
      command: input.command || 'WRITE_CHAPTER',
      instruction: input.instruction || '',
      output_requirements: input.output_requirements || ''
    },
    task: input.task || ''
  }
};

return {
  '지난 회차 데이터': {
    episode_title: input.episode_title || '',
    summary: input.summary || '',
    key_points: input.key_points || input.impact || ''
  }
};

const raw = input.rawInputs || {};
let meta = input['AI 작업 지시'] || input['AI 작업 메타'] || {};
let world = input['세계관 설정'] || input['세계관 데이터'] || {};
let properNouns = {};
let previousEpisodes = [];
let activeHooks = [];
let style = input['스타일 가이드'] || {};
let chapter = input['챕터 스코프'] || input['현재 챕터 스코프'] || {};
let characters = [];

const ingestItem = (d) => {
  if (!d || typeof d !== 'object') return;
  if (Array.isArray(d)) {
    d.forEach(sub => ingestItem(sub));
    return;
  }
  if (d.lore && typeof d.lore === 'object') {
    ingestItem(d.lore);
    return;
  }

  if (d.request || d.task) meta = { ...meta, ...d };
  if (d.title || d.background_lore) world = { ...world, ...d };

  // 단일/다중 고유명사 카드 취합
  if (d.term) {
    const catKey = d.type || '기타';
    if (!properNouns[catKey]) properNouns[catKey] = [];
    if (!properNouns[catKey].some(item => item.term === d.term)) {
      properNouns[catKey].push({ term: d.term, desc: d.desc || '' });
    }
  }
  if (d['장소'] || d['길드'] || d['세력 / 길드'] || d['현상'] || d['아이템']) {
    properNouns = { ...properNouns, ...d };
  }

  // 지난 회차 줄거리 요약 카드 취합
  if (d.episode_title || d.summary) {
    if (!previousEpisodes.some(ep => ep.episode === (d.episode_title || d.title))) {
      previousEpisodes.push({
        episode: d.episode_title || d.title || '회차',
        summary: d.summary || '',
        key_points: d.key_points || d.impact || ''
      });
    }
  }

  // 복선 노드 다중 취합 (단일 카드 또는 배열)
  if (d.active_hooks && Array.isArray(d.active_hooks)) {
    d.active_hooks.forEach(h => {
      if (!activeHooks.some(existing => existing.id === h.id && existing.hidden_truth === h.hidden_truth)) {
        activeHooks.push(h);
      }
    });
  } else if (d.hook_id || d.hidden_truth || d.observable_clue) {
    if (!activeHooks.some(existing => existing.id === (d.hook_id || d.id))) {
      activeHooks.push({
        id: d.hook_id || d.id || '복선',
        hidden_truth: d.hidden_truth || '',
        observable_clue: d.observable_clue || '',
        reveal_stage: d.reveal_stage || ''
      });
    }
  }

  if (d.project_meta && !d.request) style = { ...style, ...d };
  if (d.writing_style_guide) style = { ...style, ...d };
  if (d.episode_notation || d.must_include_events) chapter = { ...chapter, ...d };
  if (d.name && (d.role || d.traits || d.personality || d.speech_style)) {
    if (!characters.some(c => c.name === d.name)) characters.push(d);
  }
};

Object.values(raw).forEach(n => {
  const d = n.output || n.data;
  if (typeof d === 'string' && d.includes('《') && d.includes('소속:')) {
    characters.push({ description: d });
  } else {
    ingestItem(d);
  }
});

const charInput = input['등장인물'] || input['등장인물 (다중)'] || input['등장인물 데이터'] || input['프로필 데이터'];
if (charInput) ingestItem(charInput);

const histInput = input['지난 회차 (다중)'] || input['지난 회차 데이터'];
if (histInput) ingestItem(histInput);

const dictInput = input['고유명사 (다중)'] || input['고유명사 데이터'] || input['고유명사 사전'];
if (dictInput) ingestItem(dictInput);

const hookInput = input['복선 데이터 (다중)'] || input['복선 데이터'];
if (hookInput) ingestItem(hookInput);

const reqObj = meta.request || {};

const finalJson = {
  request: {
    command: reqObj.command || 'WRITE_CHAPTER',
    instruction: reqObj.instruction || '아래의 [설정값]과 [지금까지의 줄거리]를 완벽히 분석하여, [현재 챕터 범위]에 해당하는 소설 본문을 즉시 작성하시오.',
    output_requirements: reqObj.output_requirements || '사족이나 설명 없이 오직 소설 본문 텍스트(대사 및 지문)만을 출력할 것.'
  },
  project_meta: {
    role: style.project_meta?.role || '인기 웹소설 작가',
    task: meta.task || style.project_meta?.task || '소설 본문 작성'
  },
  core_experience_goal: style.core_experience_goal || { primary_emotion: '카타르시스, 도파민' },
  world_settings: world,
  characters: characters,
  proper_nouns_dict: properNouns,
  previous_episodes_history: previousEpisodes,
  foreshadowing_registry: { active_hooks: activeHooks },
  current_chapter_scope: chapter,
  writing_style_guide: style.writing_style_guide || { narrative_perspective: '3인칭 전지적 작가 시점' }
};

const jsonText = JSON.stringify(finalJson, null, 2);
return { '완성된 프롬프트': jsonText };

// 1. AI 환경 설정 수신 (AI 설정 노드 직결)
const aiConfigRaw = inputs['⚡ AI 환경 설정 (필수)'] || inputs['in_ai_config'] || inputs['AI 환경 설정'] || {};
const aiConfig = {
  provider: aiConfigRaw.provider || 'Google (Gemini)',
  model: aiConfigRaw.model || 'gemini-3.6-flash',
  apiKey: aiConfigRaw.apiKey || '',
  temperature: parseFloat(aiConfigRaw.temperature) || 0.8,
  endpoint: aiConfigRaw.endpoint || ''
};

if (!aiConfig.apiKey) {
  return {
    '📜 완성된 씬 대본': '[AI 생성 오류: API Key가 설정되지 않았습니다. [AI 설정 노드]를 연결하고 API Key를 입력해 주세요.]',
    '🧬 대본 JSON 데이터': { error: 'API Key Missing', turns: [] }
  };
}

// 2. 입력 데이터 수집 및 안전한 정규화
function extractCharacters(raw) {
  const list = [];
  function dig(item) {
    if (!item) return;
    if (Array.isArray(item)) {
      item.forEach(dig);
    } else if (typeof item === 'object') {
      if (item.persona_md || item.lore) {
        list.push({
          name: item.lore?.name || item.name || '인물 ' + (list.length + 1),
          role: item.lore?.role || item.role || '등장인물',
          persona_md: item.persona_md || '',
          lore: item.lore || item
        });
      } else if (item['등장인물 데이터']) {
        dig(item['등장인물 데이터']);
      } else {
        Object.values(item).forEach(v => {
          if (v && typeof v === 'object' && (v.persona_md || v.lore)) dig(v);
        });
      }
    }
  }
  dig(raw);
  return list;
}

const charInput = inputs['👥 등장인물 데이터 (필수)'] || inputs['in_characters'] || inputs['등장인물 데이터'] || inputs;
const charactersList = extractCharacters(charInput);

if (charactersList.length === 0) {
  return {
    '📜 완성된 씬 대본': '[AI 생성 오류: 등장인물 노드가 연결되지 않았습니다. 👥 포트에 등장인물 노드를 연결해 주세요.]',
    '🧬 대본 JSON 데이터': { error: 'Characters Missing', turns: [] }
  };
}

// 씬 상황 텍스트 추출
let sceneContext = '';
const rawScene = inputs['🎬 씬 상황 & 대화 목표 (필수)'] || inputs['in_scene'] || inputs['씬 상황 & 대화 목표'];
if (typeof rawScene === 'string') {
  sceneContext = rawScene.trim();
} else if (rawScene && typeof rawScene === 'object') {
  sceneContext = rawScene.content || rawScene.desc || rawScene.summary || JSON.stringify(rawScene);
}
if (!sceneContext) {
  sceneContext = '인물들이 마주쳐 현재 상황과 목표를 두고 대화를 시작한다.';
}

const directorNotes = (input.director_notes || '').trim();
const formatTemplate = (input.script_format_template || '').trim();
const totalTurns = Math.max(2, Math.min(30, parseInt(input.turn_count, 10) || 6));

// 3. RAG 벡터 지식 패키지 수신
const extraLoreRaw = inputs['📚 로어북 & RAG 지식 패키지 (선택)'] || inputs['in_lore'] || inputs['📚 추가 로어북 (선택)'];
let ragPackage = null;
if (extraLoreRaw && typeof extraLoreRaw === 'object') {
  if (extraLoreRaw.package_name === 'LoreVectorPackage' || extraLoreRaw['🧠 RAG 지식 패키지 (벡터 색인)']) {
    ragPackage = extraLoreRaw.package_name === 'LoreVectorPackage' ? extraLoreRaw : extraLoreRaw['🧠 RAG 지식 패키지 (벡터 색인)'];
  } else {
    ragPackage = extraLoreRaw;
  }
}

// 4. 독립된 캐릭터 에이전트 클래스
class CharacterAgent {
  constructor(charData, aiEnv) {
    this.name = charData.name;
    this.role = charData.role;
    this.persona_md = charData.persona_md;
    this.aiEnv = aiEnv;
  }

  async actTurn(turnIndex, sceneText, visibleHistory, triggeredLores, dirNotes, otherAgents, fmtTemplate) {
    const target = otherAgents[0] || { name: '상대방' };

    const systemPrompt = `${this.persona_md}\n\n# [현재 씬 상황 및 대화 목표]\n${sceneText}${dirNotes ? `\n\n[공통 연출 지침]: ${dirNotes}` : ''}${triggeredLores.length > 0 ? `\n\n[대화 중 감지된 배경 로어 지식]:\n${triggeredLores.join('\n')}` : ''}\n\n# [대본 출력 양식 지침]\n${fmtTemplate || `너는 "${this.name}"이다. 상대의 말에 반응하여 (행동), [속마음], "대사" 양식을 엄수하여 이번 1턴만 작성하라.`}`;

    const userPrompt = `[직전까지의 대화 및 행동 기록]:\n${visibleHistory || '(대화 시작)'}\n\n너는 "${this.name}"(${this.role})이다. 상대방(${target.name})에게 반응하여 다음 1턴을 작성하라.`;

    const reply = await window.aiApi.call(this.aiEnv, systemPrompt, userPrompt);

    // 🌟 초유연 다중 지문 & 괄호 파서
    const actionMatches = [...reply.matchAll(/\(([^)]+)\)|<([^>]+)>|\{([^}]+)\}|\*([^*]+)\*/g)];
    const actions = actionMatches.map(m => (m[1] || m[2] || m[3] || m[4]).trim()).filter(Boolean);
    const actionText = actions.join(' / ');

    const thoughtMatch = reply.match(/\[(?:속마음|심리|생각|내면)?:?\s*([^\]]+)\]/i) || reply.match(/\[([^\]]+)\]/);
    const thoughtText = thoughtMatch ? (thoughtMatch[1] || '').replace(/^(?:속마음|심리|생각|내면):?\s*/i, '').trim() : '';

    const speechMatch = reply.match(/"([^"]+)"|“([^”]+)”|「([^」]+)」|『([^』]+)』|'([^']+)'/);
    const speechText = speechMatch ? (speechMatch[1] || speechMatch[2] || speechMatch[3] || speechMatch[4] || speechMatch[5]).trim() : reply.replace(/\([^)]+\)|<[^>]+>|\{[^}]+\}|\*([^*]+)\*|\[[^\]]+\]/g, '').trim();

    return {
      action: actionText,
      thought: thoughtText,
      speech: speechText,
      raw_text: reply.trim()
    };
  }
}

// 5. 에이전트 인스턴스 생성
const agents = charactersList.map(c => new CharacterAgent(c, aiConfig));

// 6. 다자간 핑퐁 대본 생성 루프
const turnsLog = [];

for (let turn = 1; turn <= totalTurns; turn++) {
  const currentAgent = agents[(turn - 1) % agents.length];
  const otherAgents = agents.filter(a => a.name !== currentAgent.name);

  const visibleHistoryForCurrent = turnsLog.map(item => {
    if (item.speaker === currentAgent.name) {
      return `${item.speaker}:\n(${item.action})\n[속마음: ${item.thought}]\n${item.speech}`;
    } else {
      return `${item.speaker}:\n(${item.action})\n${item.speech}`;
    }
  }).join('\n\n');

  // 🌟 실시간 온디맨드 RAG 지식 인출 (시점 격리 적용)
  let triggeredLores = [];
  const currentTurnContext = visibleHistoryForCurrent + '\n' + sceneContext;

  if (ragPackage && window.ragEngine) {
    const searchRes = await window.ragEngine.searchVectorPackage(ragPackage, {
      query: currentTurnContext,
      characterContext: currentAgent.name,
      topK: ragPackage.defaultTopK || 3,
      maxChars: ragPackage.defaultMaxChars || 1000,
      domainFilter: ragPackage.domainFilter || 'all'
    });
    triggeredLores = searchRes.results.map(r => `[${r.title}]: ${r.content}`);
  }

  const turnResult = await currentAgent.actTurn(
    turn,
    sceneContext,
    visibleHistoryForCurrent,
    triggeredLores,
    directorNotes,
    otherAgents,
    formatTemplate
  );

  turnsLog.push({
    turn: turn,
    speaker: currentAgent.name,
    role: currentAgent.role,
    action: turnResult.action,
    thought: turnResult.thought,
    speech: turnResult.speech,
    raw_text: turnResult.raw_text
  });
}

// 7. 완결형 대본집 텍스트 조합
const scriptLines = [];
