scriptLines.push(`\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n`);

turnsLog.forEach((t, idx) => {
  scriptLines.push(`${t.speaker}:`);
