  if (idx === Math.floor(totalTurns / 2) - 1 && totalTurns >= 4) {
    scriptLines.push(`\n[상황/설명 서술 지문: 인물들 사이의 팽팽한 긴장감 속에 주변 공기가 차갑게 가라앉는다.]\n`);
  } else if (idx < turnsLog.length - 1) {
    scriptLines.push('');
  }
});

scriptLines.push(`\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n`);
scriptLines.push(`[마무리 전환 지문]`);
scriptLines.push(`대화가 일단락되며 팽팽했던 긴장감이 서서히 잦아든다. 각자의 의도와 결단을 품은 채, 다음 국면으로 이어지려 하고 있었다.`);

const fullScriptText = scriptLines.join('\n');

// 8. 스마트 가공 데이터 생성 (후속 노드 편의성 극대화)
const pureDialogueLines = turnsLog.map(t => `${t.speaker}: ${t.speech || t.action || '...'}`);
const pureDialogueText = pureDialogueLines.join('\n');

const dialoguesBySpeaker = {};
turnsLog.forEach(t => {
