// 1. 모든 연결된 입력 데이터 수집 및 플랫 배열화
const collectedItems = [];
const collectedLorebooks = [];

function harvest(item, defaultTitle = '데이터') {
  if (item === null || item === undefined) return;

  if (item.lorebook_entries && Array.isArray(item.lorebook_entries)) {
    collectedLorebooks.push(...item.lorebook_entries);
  }

  if (Array.isArray(item)) {
    item.forEach((sub, idx) => harvest(sub, `${defaultTitle} #${idx + 1}`));
  } else if (typeof item === 'object') {
    // 특정 노드 형태 판별
    if (item.persona_md || item.lore) {
      if (item.lorebook_entries && Array.isArray(item.lorebook_entries)) {
        collectedLorebooks.push(...item.lorebook_entries);
      }
      collectedItems.push({
        title: item.lore?.name || item.name || defaultTitle,
        type: 'character',
        text: item.persona_md || (typeof item.lore === 'object' ? JSON.stringify(item.lore, null, 2) : String(item.lore)),
        raw: item
      });
    } else if (item.scene_overview || item.plot_beats) {
      collectedItems.push({
        title: '🎬 시나리오 비트 데이터',
        type: 'scenario',
        text: item.raw_scenario || JSON.stringify(item, null, 2),
        raw: item
      });
    } else if (item['📜 완성된 씬 대본'] || item.turns) {
      collectedItems.push({
        title: '🎭 씬 대본집',
        type: 'dialogue_script',
        text: item['📜 완성된 씬 대본'] || item.script || JSON.stringify(item, null, 2),
        raw: item
      });
    } else if (item.content !== undefined || item.editorVal !== undefined || item.val !== undefined || item.text !== undefined || item.desc !== undefined) {
      const textVal = item.content || item.editorVal || item.val || item.text || item.desc || '';
      collectedItems.push({
        title: item.title || item.name || defaultTitle,
        type: 'text_node',
        text: typeof textVal === 'object' ? JSON.stringify(textVal, null, 2) : String(textVal),
        raw: item
      });
    } else {
      const keys = Object.keys(item);
      if (keys.length > 0) {
        keys.forEach(k => {
          if (k !== 'input' && k !== 'rawInputs' && k !== 'displayVal' && k !== 'merged_viewer') {
            harvest(item[k], k);
          }
        });
      } else {
        collectedItems.push({
          title: defaultTitle,
          type: 'json_object',
          text: JSON.stringify(item, null, 2),
          raw: item
        });
      }
    }
  } else {
    const textVal = String(item).trim();
    if (textVal) {
      collectedItems.push({
        title: defaultTitle,
        type: 'raw_text',
        text: textVal,
        raw: item
      });
    }
  }
}

// 1) 명시적 포트 데이터 추출
