if (collectedItems.length === 0 && inputs && typeof inputs === 'object') {
  Object.entries(inputs).forEach(([key, val]) => {
    if (key !== 'in_nodes' && key !== 'in_extra' && key !== 'input' && key !== 'rawInputs') {
