// 2. 위젯 설정 및 병합 모드 처리
const mergeMode = (input.merge_mode || '📌 스마트 섹션 마크다운 (제목 + 내용 자동 구분)').trim();
const prefix = (input.custom_prefix || '').trim();

let mergedText = '';
const textBlocks = [];

if (prefix) {
  textBlocks.push(prefix);
}

if (mergeMode.includes('스마트 섹션')) {
  collectedItems.forEach((it, idx) => {
    let block = '';
    if (it.text.startsWith('#')) {
      block = it.text;
    } else {
      block = `## [${it.title || `항목 ${idx + 1}`}]\n${it.text}`;
    }
    textBlocks.push(block);
  });
  mergedText = textBlocks.join('\n\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\n');
} else if (mergeMode.includes('구분선')) {
  collectedItems.forEach(it => textBlocks.push(it.text));
  mergedText = textBlocks.join('\n\n---\n\n');
} else if (mergeMode.includes('단순 줄바꿈')) {
  collectedItems.forEach(it => textBlocks.push(it.text));
  mergedText = textBlocks.join('\n\n');
} else if (mergeMode.includes('JSON')) {
  const jsonArr = collectedItems.map(it => it.raw);
  mergedText = JSON.stringify(jsonArr, null, 2);
} else {
  collectedItems.forEach(it => textBlocks.push(`### ${it.title}\n${it.text}`));
  mergedText = textBlocks.join('\n\n');
}

// 중복 로어북 제거
const uniqueLorebooks = [];
const seenLoreIds = new Set();
collectedLorebooks.forEach(lb => {
  if (lb && lb.id && !seenLoreIds.has(lb.id)) {
    seenLoreIds.add(lb.id);
    uniqueLorebooks.push(lb);
  } else if (lb && !lb.id) {
    uniqueLorebooks.push(lb);
  }
});

// 3. 최종 출력 반환
return {
