  '📚 패키징된 로어북 지식 (마크다운)': formattedMd
};

// 1. 검색 쿼리 획득 (동적 포트 입력 우선, 없으면 위젯 입력값)
let query = inputs['🔍 동적 검색 쿼리 (선택)'] || inputs['in_query'] || input.search_query || '';
if (query && typeof query === 'object') {
  query = query.content || query.text || query.summary || query.val || JSON.stringify(query);
}
query = String(query || '').trim();

if (!query) {
  return {
    '📜 검색된 RAG 로어 지식 (마크다운)': '(검색 쿼리가 비어있습니다. [검색 쿼리 / 질문 / 상황 문맥] 입력란에 검색할 키워드나 상황을 입력해 주세요.)',
    '🧬 검색 결과 데이터 (JSON / 배열)': { query: '', count: 0, results: [] }
  };
}

// 2. 위젯 검색 파라미터 획득
const topK = Number(input.top_k || 3);
const maxChars = Number(input.max_chars || 1000);
let domainFilter = input.domain_filter || '전체 (All Domains)';
if (domainFilter.includes('인물')) domainFilter = 'character';
else if (domainFilter.includes('세계관')) domainFilter = 'world';
else if (domainFilter.includes('고유명사')) domainFilter = 'proper_noun';
else if (domainFilter.includes('복선')) domainFilter = 'foreshadowing';
else domainFilter = 'all';

const characterContext = String(input.character_context || '').trim();

// 3. 입력 RAG 지식 수집
const rawRAG = inputs['📚 RAG 패키지 / 로어 데이터 (필수)'] || inputs['in_rag_sources'] || inputs;

if (!window.ragEngine) {
  return {
    '📜 검색된 RAG 로어 지식 (마크다운)': '[오류: RAG 엔진이 준비되지 않았습니다.]',
    '🧬 검색 결과 데이터 (JSON / 배열)': { error: 'RAG Engine Not Ready' }
  };
}

// 4. RAG 벡터 유사도 검색 실행
const searchRes = await window.ragEngine.searchVectorPackage(rawRAG, {
  query,
  topK,
  maxChars,
  domainFilter,
  characterContext
});

// 5. 마크다운 결과 조립
let formattedMarkdown = '';
if (searchRes.results && searchRes.results.length > 0) {
  formattedMarkdown = `# [🔍 RAG 검색 결과: "${query}"] (총 ${searchRes.results.length}건 인출)\n\n` +
    searchRes.results.map((r, i) => {
      const scorePct = Math.round(r.score * 100);
      return `### ${i + 1}. [${r.domain.toUpperCase()}] ${r.title} (🎯 일치율 ${scorePct}%)\n${r.content}`;
    }).join('\n\n');
} else {
  formattedMarkdown = `# [🔍 RAG 검색 결과: "${query}"]\n\n조건에 일치하는 로어 지식을 찾지 못했습니다.`;
}

return {
  '📜 검색된 RAG 로어 지식 (마크다운)': formattedMarkdown,
  '🧬 검색 결과 데이터 (JSON / 배열)': {
    query,
    count: searchRes.results?.length || 0,
    topK,
    maxChars,
    domainFilter,
    characterContext,
    results: searchRes.results || []
  }
};
